<?php
session_start();
require_once __DIR__.'/../config/config.php';
$active_zone='exchange';
$keyword=trim($_GET['q']??'');$condition=trim($_GET['condition']??'');$category=trim($_GET['category']??'');$sort=$_GET['sort']??'latest';
$page=max(1,(int)($_GET['page']??1));$perPage=12;$offset=($page-1)*$perPage;
$where=["e.status='open'"];$params=[];
if($keyword!==''){$where[]='(e.title LIKE :keyword OR e.author LIKE :keyword OR e.isbn LIKE :keyword)';$params[':keyword']="%$keyword%";}
if(in_array($condition,['99','90','80','70'],true)){$where[]='e.condition_percent=:condition';$params[':condition']=$condition;}
if($category!==''){$where[]='e.category=:category';$params[':category']=$category;}
$whereSql=implode(' AND ',$where);
$orderSql=match($sort){'oldest'=>'e.created_at ASC','condition'=>'CAST(e.condition_percent AS UNSIGNED) DESC,e.created_at DESC','title'=>'e.title ASC',default=>'e.created_at DESC,e.exchange_id DESC'};
$count=$pdo->prepare("SELECT COUNT(*) FROM exchanges e WHERE $whereSql");$count->execute($params);$total=(int)$count->fetchColumn();$totalPages=max(1,(int)ceil($total/$perPage));
$stmt=$pdo->prepare("SELECT e.*, e.owner_lat, e.owner_lng, e.owner_province FROM exchanges e WHERE $whereSql ORDER BY $orderSql LIMIT :limit OFFSET :offset");foreach($params as $key=>$value)$stmt->bindValue($key,$value);$stmt->bindValue(':limit',$perPage,PDO::PARAM_INT);$stmt->bindValue(':offset',$offset,PDO::PARAM_INT);$stmt->execute();$exchanges=$stmt->fetchAll(PDO::FETCH_ASSOC);
$categories=$pdo->query("SELECT DISTINCT category FROM exchanges WHERE status='open' AND category IS NOT NULL AND category<>'' ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);
$breadcrumbs=[['label'=>'หน้าหลัก','url'=>'/pages/home.php'],['label'=>'ลานแลกเปลี่ยนหนังสือ','url'=>'/pages/exchange_books.php'],['label'=>'ผลการกรอง','url'=>'']];
function ecImage(?string $value):?string{if(!$value)return null;if(preg_match('#^https?://#i',$value))return $value;$value=ltrim(str_replace('\\','/',$value),'/');return str_starts_with($value,'uploads/')?'/pages/'.$value:'/assets/image/books/'.$value;}
function ecQuery(array $changes=[]):string{$query=array_merge($_GET,$changes);foreach($query as $key=>$value)if($value===''||$value===null)unset($query[$key]);return '?'.http_build_query($query);}
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ผลการกรองรายการแลกเปลี่ยน - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css?v=<?= filemtime(__DIR__.'/../assets/css/styles.css') ?>"><style>
*{box-sizing:border-box}.wrap{max-width:1200px;margin:auto;padding:32px 40px 80px}.title{display:flex;align-items:center;gap:14px;color:var(--secondary-color);font-size:36px;margin:0 0 25px}.title svg{width:42px;height:42px}.filters{border:1px solid #d8ddd4;border-radius:14px;padding:20px 24px;background:#fff;box-shadow:0 3px 8px #00000012}.filter-grid{display:grid;grid-template-columns:1.7fr 1fr 1fr;gap:14px}.field label{display:block;color:var(--secondary-color);font-size:var(--text-sm);font-weight:600;margin-bottom:6px}.field input,.field select{width:100%;height:40px;border:1px solid var(--border-color);border-radius:8px;padding:0 11px;font-family:var(--font-family)}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:14px}.btn{min-width:110px;height:38px;border:1px solid #d3948b;border-radius:8px;font-family:var(--font-family);display:grid;place-items:center;text-decoration:none;cursor:pointer}.submit{background:#d3948b;color:#fff}.reset{background:#fff;color:#d3948b}.results{display:flex;justify-content:space-between;align-items:center;border:1px solid #d8ddd4;border-radius:12px;padding:15px 26px;margin:34px 0;color:var(--secondary-color);font-weight:600;box-shadow:0 2px 6px #00000010}.sort{display:flex;align-items:center;gap:10px}.sort select{height:38px;border:1px solid #d8ddd4;border-radius:8px;padding:0 10px;font-family:var(--font-family)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.empty{grid-column:1/-1;text-align:center;padding:80px;color:var(--text-muted)}.pagination{display:flex;justify-content:center;gap:10px;margin-top:48px}.pagination a{width:44px;height:44px;border:1px solid #secondary-color);border-radius:8px;display:grid;place-items:center;text-decoration:none;color:var(--secondary-color);font-weight:600}.pagination .active{background:var(--secondary-color);color:#fff}@media(max-width:900px){.filter-grid,.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.wrap{padding:24px 18px 60px}.filter-grid,.grid{grid-template-columns:repeat(2, 1fr)}.results{align-items:flex-start;flex-direction:column;gap:12px}.title{font-size:28px}}
</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="wrap"><h1 class="title"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M7 7h11l-3-3M18 7l-3 3M17 17H6l3 3M6 17l3-3"/></svg>ผลการกรองรายการแลกเปลี่ยน</h1><form class="filters" method="get"><div class="filter-grid"><div class="field"><label>ค้นหาตามชื่อ/ผู้แต่ง</label><input name="q" value="<?=htmlspecialchars($keyword)?>" placeholder="พิมพ์ชื่อหนังสือที่คุณกำลังตามหา..."></div><div class="field"><label>สภาพหนังสือ</label><select name="condition"><option value="">ทั้งหมด</option><?php foreach(['99'=>'เหมือนใหม่ 99%','90'=>'สภาพดี 90%','80'=>'สภาพปานกลาง 80%','70'=>'มีร่องรอย 70%'] as $value=>$label):?><option value="<?=$value?>" <?=$condition===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div class="field"><label>หมวดหมู่</label><select name="category"><option value="">ทั้งหมด</option><?php foreach($categories as $value):?><option <?=$category===$value?'selected':''?>><?=htmlspecialchars($value)?></option><?php endforeach;?></select></div></div><div class="actions"><button class="btn submit">กรองข้อมูล</button><a class="btn reset" href="/pages/exchange_catalog.php">ล้าง</a></div></form><div class="results"><span>แสดงผลลัพธ์ที่ <?=$total?($offset+1).'–'.min($offset+$perPage,$total):'0'?> จากทั้งหมด <?=number_format($total)?> รายการ</span><form class="sort"><?php foreach($_GET as $key=>$value):if($key==='sort'||$key==='page')continue;?><input type="hidden" name="<?=htmlspecialchars($key)?>" value="<?=htmlspecialchars($value)?>"><?php endforeach;?><label>จัดเรียงตาม:</label><select name="sort" onchange="this.form.submit()"><option value="latest" <?=$sort==='latest'?'selected':''?>>ใหม่ล่าสุด</option><option value="oldest" <?=$sort==='oldest'?'selected':''?>>เก่าสุด</option><option value="condition" <?=$sort==='condition'?'selected':''?>>สภาพดีที่สุด</option><option value="title" <?=$sort==='title'?'selected':''?>>ชื่อหนังสือ</option></select></form></div><div class="grid"><?php if(!$exchanges):?><p class="empty">ไม่พบประกาศแลกเปลี่ยนตามตัวกรอง</p><?php else:foreach($exchanges as $row){$book=['id'=>(int)$row['exchange_id'],'title'=>$row['title'],'author'=>$row['author']??'','price'=>0,'badge'=>'แลกเปลี่ยน','image'=>ecImage($row['image_cover']??null),'seller_type'=>'user','owner_province'=>$row['owner_province']??'','owner_lat'=>$row['owner_lat']??null,'owner_lng'=>$row['owner_lng']??null,'stock_quantity'=>1];$card_type='exchange';require __DIR__.'/../components/book_card.php';}endif;?></div><?php if($totalPages>1):?><nav class="pagination"><?php for($p=1;$p<=$totalPages;$p++):?><a class="<?=$p===$page?'active':''?>" href="<?=htmlspecialchars(ecQuery(['page'=>$p]))?>"><?=$p?></a><?php endfor;?></nav><?php endif;?></main><?php require __DIR__.'/../components/footer.php';?></body></html>
